additionalExercises.referenceSolution:
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <memory>
#include <print>
#include <string>

int allocated = 0;
int freed = 0;

// Условная C-библиотека.
extern "C" char *c_greet(const char *name) {
    const std::string text = std::string("Привет, ") + name + "!";
    char *out = static_cast<char *>(std::malloc(text.size() + 1));
    std::memcpy(out, text.c_str(), text.size() + 1);
    ++allocated;
    return out;
}

extern "C" int c_reverse(const char *s, char **out) {
    const std::size_t n = std::strlen(s);
    if (n == 0) {
        return -1;
    }
    *out = static_cast<char *>(std::malloc(n + 1));
    for (std::size_t i = 0; i < n; ++i) {
        (*out)[i] = s[n - 1 - i];
    }
    (*out)[n] = '\0';
    ++allocated;
    return 0;
}

extern "C" void c_free(void *p) {
    if (p) {
        ++freed;
    }
    std::free(p);
}

struct CFree {
    void operator()(char *p) const noexcept {
        c_free(p);
    }
};

using CString = std::unique_ptr<char, CFree>;

void stats() {
    std::println("выделено {}, освобождено {}", allocated, freed);
}

int main() {
    std::string command;
    while (std::cin >> command) {
        if (command == "stats") {
            stats();
            continue;
        }
        std::string arg;
        std::cin >> arg;
        if (command == "greet") {
            const CString s(c_greet(arg.c_str()));
            std::println("{}", s.get());
        } else {
            CString out;
            if (c_reverse(arg.c_str(), std::out_ptr(out)) == 0) {
                std::println("{}", out.get());
            } else {
                std::println("пусто");
            }
        }
    }
    stats();
    return 0;
}

