#include <memory>
#include <print>

struct Noisy {
    void operator()(int *p) const {
        std::print("[{}]", *p);
        delete p;
    }
};

int main() {
    std::unique_ptr<int, Noisy> a(new int(1));
    std::unique_ptr<int, Noisy> b(new int(2));
    a = std::move(b);
    std::print("|");
    return 0;
}
